class Solution {
public:
    int tripletCount(vector<int>& a, vector<int>& b, vector<int>& c) {
        auto eo = [](vector<int>& v) {
            long long e = 0;
            for (int x : v) e += __builtin_popcount(x) % 2 == 0;
            return make_pair(e, (long long)v.size() - e);
        };
        auto [ea, oa] = eo(a);
        auto [eb, ob] = eo(b);
        auto [ec, oc] = eo(c);
        return ea*eb*ec + ea*ob*oc + oa*eb*oc + oa*ob*ec;
    }
};

