class Solution {
    public int tripletCount(int[] a, int[] b, int[] c) {
        long ea = 0, eb = 0, ec = 0;
        for (int x : a) ea += Integer.bitCount(x) % 2 == 0 ? 1 : 0;
        for (int x : b) eb += Integer.bitCount(x) % 2 == 0 ? 1 : 0;
        for (int x : c) ec += Integer.bitCount(x) % 2 == 0 ? 1 : 0;
        long oa = a.length - ea, ob = b.length - eb, oc = c.length - ec;
        return (int)(ea*eb*ec + ea*ob*oc + oa*eb*oc + oa*ob*ec);
    }
}

